	@Test
	void sharesEquivalentRequestsEvenWhenTheirResourceIndicesDiffer() {
		List<Node> original = original();
		Aggregate terminal = countDistinct();
		List<Node> rewritten = rewrite(original, terminal, requests(), domains());
		assertEquals(3, rewritten.size());
		assertSame(((Union) original.get(0)).branches.get(0).get(0), rewritten.get(0));
		assertSame(((Union) original.get(0)).branches.get(0).get(1), rewritten.get(1));
		Exists witness = (Exists) rewritten.get(2);
		assertFalse(witness.negated);
		Union tails = (Union) witness.pipeline.get(0);
		assertEquals(0, tails.resetColumns().length, "the witness must retain its bound entity register");
		assertEquals(2, tails.branches.size());
		Kernel kernel = new Kernel(2, rewritten, terminal);
		Aggregate kept = (Aggregate) kernel.terminal;
		assertEquals(LmdbNativeKernelIr.AGG_COUNT_DISTINCT, kept.outputs[0].kind);
		assertEquals(-1, kept.outputs[0].orderedDomain);
		assertFalse(LmdbNativeKernelEmitter.emit(kernel).contains("KernelProjectionCursor.Owner"));
	}

	@Test
	void onlyAnOrderInsensitiveGlobalSingleHashDistinctConsumerQualifies() {
		List<Node> original = original();
		List<Aggregate> rejected = List.of(
				terminal(AggregateOutput.countStar()), terminal(AggregateOutput.count(1)),
				terminal(AggregateOutput.sumDistinct(1)), terminal(AggregateOutput.countDistinct(0)),
				terminal(AggregateOutput.countDistinctOrdered(1, 0)),
				terminal(AggregateOutput.countDistinct(1).asHookDistinct()),
				new Aggregate(new int[] { 0 }, new AggregateOutput[] { AggregateOutput.countDistinct(1) }, null,
						OutputMods.none()),
				new Aggregate(new int[0], new AggregateOutput[] { AggregateOutput.countDistinct(1),
						AggregateOutput.countStar() }, null, OutputMods.none()));
		for (Aggregate aggregate : rejected) {
			assertSame(original, rewrite(original, aggregate, requests(), domains()));
		}
		assertSame(original,
				LmdbNativeDistinctUnionPrefix.optimize(original, countDistinct(), requests(), domains(), true));
	}

	@Test
	void everyAdjacencyIdentityAndAdmissionFieldMustMatch() {
		List<Node> original = original();
		for (int index : new int[] { 2, 3 }) {
			AdjacencyRequest expected = requests().get(index);
			for (AdjacencyRequest mismatch : List.of(
					new AdjacencyRequest(expected.predicate + 1, expected.bySubject, false, false),
					new AdjacencyRequest(expected.predicate, !expected.bySubject, false, false),
					new AdjacencyRequest(expected.predicate, expected.bySubject, true, false),
					new AdjacencyRequest(expected.predicate, expected.bySubject, false, true))) {
				List<AdjacencyRequest> changed = new ArrayList<>(requests());
				changed.set(index, mismatch);
				assertSame(original, rewrite(original, countDistinct(), changed, domains()));
			}
		}
	}

