	@Test
	void performsOneCodeScanAndSkipsTheSecondSuccessfulTypeArm() throws Exception {
		long[][] codes = { { 10, 1, 2, 3 }, { 20, 4 }, { 80, 5 } };
		long[][] types = { { 1, 1000 }, { 2, 1000 }, { 3, 1000 }, { 4, 1000 }, { 5, 1000 } };
		for (boolean interpreted : new boolean[] { false, true }) {
			Rows[] before = fixture(codes, types), after = fixture(codes, types);
			assertEquals(List.of(5L), evaluate(original(), countDistinct(), before, interpreted));
			assertEquals(List.of(5L), evaluate(rewrite(original(), countDistinct(), requests(), domains()),
					countDistinct(), after, interpreted));
			assertEquals(10, before[0].reads + before[2].reads);
			assertEquals(5, after[0].reads + after[2].reads);
			assertEquals(5, before[3].finds);
			assertEquals(0, after[3].finds);
		}
	}

