	private static List<Node> changedRight(Node... nodes) {
		return List.of(new Union(List.of(branch(0, 0, 1, 0), List.of(nodes))));
	}

	private static List<Node> original() {
		return List.of(new Union(List.of(branch(0, 0, 1, 0), branch(1, 2, 3, 1))));
	}

	private static List<Node> branch(int domain, int adjacency, int types, int target) {
		return List.of(new EnumerateDomain(domain, 0), new Probe(adjacency, Operand.col(0), 1), close(types, target));
	}

	private static ProbeClose close(int adjacency, int target) {
		return new ProbeClose(adjacency, Operand.col(1), Operand.constant(target), true, true);
	}

	private static Aggregate countDistinct() {
		return terminal(AggregateOutput.countDistinct(1));
	}

	private static Aggregate terminal(AggregateOutput output) {
		return new Aggregate(new int[0], new AggregateOutput[] { output }, null, OutputMods.none());
	}

	private static List<AdjacencyRequest> requests() {
		return List.of(new AdjacencyRequest(500, false, false), new AdjacencyRequest(600, true, false),
				new AdjacencyRequest(500, false, false), new AdjacencyRequest(600, true, false));
	}

	private static List<DomainRequest> domains() {
		return List.of(new DomainRequest(DOMAIN.clone()), new DomainRequest(DOMAIN.clone()));
	}

	private static List<Node> rewrite(List<Node> original, Aggregate terminal, List<AdjacencyRequest> requests,
			List<DomainRequest> domains) {
		return LmdbNativeDistinctUnionPrefix.optimize(original, terminal, requests, domains, false);
	}

	private static Rows[] fixture(long[][] codes, long[][] types) {
		return new Rows[] { new Rows(codes), new Rows(types), new Rows(codes), new Rows(types) };
	}

	private static List<Long> evaluate(List<Node> pipeline, Aggregate terminal, Rows[] adjacency, boolean interpreted)
			throws Exception {
		Kernel ir = new Kernel(2, pipeline, terminal);
		JaninoKernel kernel;
		if (interpreted) {
			kernel = LmdbNativeKernelInterpreter.forAggregate(ir);
		} else {
			SimpleCompiler compiler = new SimpleCompiler();
			compiler.setSourceVersion(8);
			compiler.setTargetVersion(8);
			compiler.setParentClassLoader(JaninoKernel.class.getClassLoader());
			compiler.cook(LmdbNativeKernelEmitter.emit(ir));
			kernel = (JaninoKernel) compiler.getClassLoader().loadClass(ir.className()).getConstructor().newInstance();
		}
		assertNotNull(kernel);
		try {
			kernel.bind(new KernelContext(adjacency, TYPES, new long[0], new long[][] { DOMAIN, DOMAIN.clone() },
					new Hooks()));
			List<Long> rows = new ArrayList<>();
			long[] buffer = new long[1];
			assertEquals(0, kernel.fill(buffer, 0));
			while (kernel.fill(buffer, 1) != 0)
				rows.add(buffer[0]);
			return rows;
		} finally {
			kernel.close();
		}
	}

	private static final class Rows implements NativeAdjacency {
		final long[][] rows;
		int finds;
		int reads;

		Rows(long[][] rows) {
			this.rows = rows;
		}

		@Override
		public long find(long key) {
			finds++;
			for (int i = 0; i < rows.length; i++)
				if (rows[i][0] == key)
					return i + 1L;
			return NOT_FOUND;
		}

		@Override
		public long size(long handle) {
			return rows[(int) handle - 1].length - 1;
		}

		@Override
		public long neighborAt(long handle, long offset) {
			reads++;
			return rows[(int) handle - 1][(int) offset + 1];
		}

		@Override
		public long contextAt(long handle, long offset) {
			return offset + 1;
		}
	}

	private static final class Hooks implements KernelHooks {
		@Override
		public KernelHooks keySemantics() {
			return this;
		}

		@Override
		public boolean isBoundValue(long id) {
			return id != -1L && id != 0L;
		}

		@Override
		public boolean sameRdfTerm(long left, long right) {
			return normalized(left) == normalized(right);
		}

		@Override
		public long rdfTermHash(long id) {
			return normalized(id);
		}

		private long normalized(long id) {
			return id == 101 ? 100 : id;
		}

		@Override
		public boolean testFilter(int id, long a, long b, long c) {
			throw new AssertionError("filter hook");
		}

		@Override
		public long computeBind(int id, long a, long b) {
			throw new AssertionError("bind hook");
		}

		@Override
		public int compareValues(long a, long b) {
			return Long.compare(a, b);
		}

		@Override
		public boolean isNumeric(long id) {
			return false;
		}

		@Override
		public double doubleValue(long id) {
			throw new AssertionError("numeric hook");
		}

		@Override
		public void accumulateNumeric(int aggregate, int group, long value) {
			throw new AssertionError("numeric aggregate");
		}
	}
